contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            (beforeC >= amount && !reverted && afterThis == beforeThis + amount && afterC == beforeC - amount && afterDeposits == beforeDeposits)
            ||
            (beforeC < amount && reverted && afterC == beforeC && afterThis == beforeThis && afterDeposits == beforeDeposits)
        );
    }

    receive() external payable {}
}

